package br.com.fiap.bank.plataforma.exception;
import br.com.fiap.bank.plataforma.application.RecursoNaoEncontradoException; import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import java.util.*; @RestControllerAdvice public class GlobalExceptionHandler { @ExceptionHandler(RecursoNaoEncontradoException.class) public ResponseEntity<Map<String,Object>> notFound(RuntimeException e){return ResponseEntity.status(404).body(Map.of("erro","Não encontrado","mensagem",e.getMessage()));} @ExceptionHandler({IllegalArgumentException.class,IllegalStateException.class}) public ResponseEntity<Map<String,Object>> invalid(RuntimeException e){return ResponseEntity.status(409).body(Map.of("erro","Operação inválida","mensagem",e.getMessage()));} @ExceptionHandler(MethodArgumentNotValidException.class) public ResponseEntity<Map<String,Object>> validation(MethodArgumentNotValidException e){return ResponseEntity.badRequest().body(Map.of("erro","Dados inválidos","detalhes",e.getBindingResult().getFieldErrors().stream().map(x->x.getField()+": "+x.getDefaultMessage()).toList()));} }
